<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'open';$notes=trim($_POST['resolution_notes']??'');if(!in_array($status,['open','in_progress','resolved'],true)){flash('error','Invalid complaint status.');redirect('complaints.php');}$pdo->prepare("UPDATE complaints SET status=?,resolution_notes=?,resolved_at=IF(?='resolved',NOW(),NULL),assigned_to=? WHERE id=?")->execute([$status,$notes,$status,current_user()['id'],$id]);audit($pdo,'UPDATE COMPLAINT',"Complaint #$id: $status");flash('success','Complaint updated.');redirect('complaints.php');}
$rows=$pdo->query("SELECT x.*,c.full_name,c.account_number FROM complaints x JOIN customers c ON c.id=x.customer_id ORDER BY x.created_at DESC")->fetchAll();$pageTitle='Complaints management';require 'includes/header.php';
?>
<div class="panel"><div class="panel-head"><h3>Customer complaints</h3><input class="search-input" data-table-search="complaints-table" placeholder="Search complaints..."></div><div class="table-wrap"><table id="complaints-table"><thead><tr><th>Customer</th><th>Subject</th><th>Description</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small class="table-sub"><?=e($r['account_number'])?></small></td><td><?=e($r['subject'])?></td><td class="description-cell"><?=e($r['description'])?></td><td><span class="pill <?=$r['status']==='resolved'?'success':($r['status']==='in_progress'?'info':'warning')?>"><?=e(str_replace('_',' ',ucfirst($r['status'])))?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="open" <?=$r['status']==='open'?'selected':''?>>Open</option><option value="in_progress" <?=$r['status']==='in_progress'?'selected':''?>>In progress</option><option value="resolved" <?=$r['status']==='resolved'?'selected':''?>>Resolved</option></select><input name="resolution_notes" placeholder="Resolution notes" value="<?=e($r['resolution_notes'])?>"><button class="btn small">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No complaints submitted.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
